function nombreMarca(titulo, dom) {
  const base = String(dom || '').split('.')[0];
  if (base && base.length >= 5) return base;
  return norm(String(titulo || '').split(/[|\-:,]/)[0]).replace(/[^a-z0-9 ]/g, '').trim();
}

